// ErrInsecureBaseURL is what every call answers when the client's base URL is
// not https and not a loopback address, before anything is sent: the API key
// would cross the network in clear text.
var ErrInsecureBaseURL = errors.New("meeng: the base URL must be https (http is accepted only for localhost, 127.0.0.0/8 and ::1), so the API key is never sent in clear text")

// ErrMissingAPIKey is what every call answers when no API key was given and
// MEENG_API_KEY is not set.
var ErrMissingAPIKey = errors.New("meeng: missing API key: pass it to New or set MEENG_API_KEY")

// Client talks to meeng's API with one team's API key.
type Client struct {
	apiKey  string
	baseURL string
	http    *http.Client
	// maxRetries and retryDelay are how a call that may be repeated is repeated.
	maxRetries int
	retryDelay time.Duration
	// setupErr is why the client cannot call, answered by every call.
	setupErr     error
	Emails       *EmailsService
	Domains      *DomainsService
	Contacts     *ContactsService
	ContactBooks *ContactBooksService
	Campaigns    *CampaignsService
	Analytics    *AnalyticsService
}

// Option configures a Client.
type Option func(*Client)

// WithBaseURL points the client at another app, such as a self-hosted one:
// the address of the app, without /api/v1. It must be https; http is
// accepted only for localhost, 127.0.0.0/8 and ::1, and any other address
// makes every call answer ErrInsecureBaseURL.
func WithBaseURL(baseURL string) Option {
	return func(c *Client) { c.baseURL = strings.TrimRight(baseURL, "/") }
}

// WithHTTPClient sends the requests through httpClient. The default client
// refuses redirects, so the API key never follows one; a client given here
// decides for itself.
func WithHTTPClient(httpClient *http.Client) Option {
	return func(c *Client) { c.http = httpClient }
}

// DefaultMaxRetries is how many times a call that may be repeated is repeated
// after the first attempt.
const DefaultMaxRetries = 2

// DefaultRetryDelay is the wait before the first repetition; each one waits
// twice as long as the one before, up to MaxRetryDelay.
const DefaultRetryDelay = 500 * time.Millisecond

// MaxRetryDelay is the longest a call waits before a repetition, whether the
// wait comes from the backoff or from the Retry-After the API answered.
const MaxRetryDelay = 30 * time.Second

// WithMaxRetries sets how many times a call that may be repeated is repeated
// after the first attempt (2 by default); 0 sends every call once. A call is
// repeated when the API answers 429 (the call was not processed, so any call
// may be repeated), and when it answers 500, 502, 503 or 504, or the
// connection fails, only if repeating it cannot do the work twice: a read, a
// PUT, a DELETE, or any call that carries an Idempotency-Key. Nothing else is
// ever repeated, and a 409 never is.
func WithMaxRetries(n int) Option {
	return func(c *Client) { c.maxRetries = n }
}

// WithRetryDelay sets the wait before the first repetition (500 ms by
// default); each repetition waits twice as long as the one before, and a
// Retry-After the API answers replaces the wait.
func WithRetryDelay(d time.Duration) Option {
	return func(c *Client) { c.retryDelay = d }
}

// New is a client for the team apiKey belongs to. An empty apiKey is read from
// MEENG_API_KEY, and the base URL, unless WithBaseURL gives one, from
// MEENG_BASE_URL.
func New(apiKey string, opts ...Option) *Client {
	if apiKey == "" {
		apiKey = os.Getenv("MEENG_API_KEY")
	}
	baseURL := os.Getenv("MEENG_BASE_URL")
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	c := &Client{apiKey: apiKey, baseURL: strings.TrimRight(baseURL, "/"), maxRetries: DefaultMaxRetries, retryDelay: DefaultRetryDelay, http: &http.Client{
		Timeout: 30 * time.Second,
		// The API never redirects, and a redirect would carry the key along:
		// the 3xx is the answer, and an Error.
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}}
	for _, opt := range opts {
		opt(c)
	}
	switch {
	case c.apiKey == "":
		c.setupErr = ErrMissingAPIKey
	default:
		c.setupErr = checkBaseURL(c.baseURL)
	}
	c.initServices()
	return c
}

// Webhooks checks and reads the webhooks a team's endpoint receives.
func (c *Client) Webhooks(secret string) *Webhooks { return NewWebhooks(secret) }

// checkBaseURL refuses an address that is not https, unless it is loopback.
func checkBaseURL(baseURL string) error {
	u, err := url.Parse(baseURL)
	if err != nil || u.Host == "" {
		return ErrInsecureBaseURL
	}
	switch strings.ToLower(u.Scheme) {
	case "https":
		return nil
	case "http":
		host := strings.ToLower(u.Hostname())
		if host == "localhost" {
			return nil
		}
		if ip := net.ParseIP(host); ip != nil && ip.IsLoopback() {
			return nil
		}
	}
	return ErrInsecureBaseURL
}

// RequestOption configures one call.
type RequestOption func(*requestConfig)

type requestConfig struct {
	idempotencyKey string
}

// WithIdempotencyKey makes a send safe to retry: the same key with the same
// body answers the first result again; with another body, a 409 NOT_UNIQUE.
// The key is up to 256 characters and expires after 24 hours. The API reads it
// on emails.send and emails.batch.
func WithIdempotencyKey(key string) RequestOption {
	return func(r *requestConfig) { r.idempotencyKey = key }
}

func (c *Client) do(ctx context.Context, method, path string, query url.Values, body any, out any, opts []RequestOption) error {
	if c.setupErr != nil {
		return c.setupErr
	}
	var config requestConfig
	for _, opt := range opts {
		opt(&config)
	}
	target := c.baseURL + apiPrefix + path
	if len(query) > 0 {
		target += "?" + query.Encode()
	}
	var encoded []byte
	if body != nil {
		var err error
		if encoded, err = json.Marshal(body); err != nil {
			return err
		}
	}
	retryable := repeatable(method, config.idempotencyKey)
	for attempt := 0; ; attempt++ {
		wait, err := c.attempt(ctx, method, target, encoded, config.idempotencyKey, out)
		if err == nil {
			return nil
		}
		var refusal *Error
		isRefusal := errors.As(err, &refusal)
		again := false
		switch {
		case isRefusal && refusal.StatusCode == http.StatusTooManyRequests:
			again = true
		case isRefusal:
			again = retryable && transient(refusal.StatusCode)
		default:
			// The connection failed: the call may or may not have arrived.
			again = retryable && ctx.Err() == nil && !isDecodeError(err)
		}
		if !again || attempt >= c.maxRetries {
			return err
		}
		if wait <= 0 {
			wait = c.backoff(attempt)
		}
		if wait > MaxRetryDelay {
			wait = MaxRetryDelay
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			timer.Stop()
			return err
		case <-timer.C:
		}
	}
}

// attempt sends one request. The wait it returns is the Retry-After of a
// refusal, or zero.
func (c *Client) attempt(ctx context.Context, method, target string, encoded []byte, idempotencyKey string, out any) (time.Duration, error) {
	var reader io.Reader
	if encoded != nil {
		reader = bytes.NewReader(encoded)
	}
	req, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return 0, err
	}
	req.Header.Set("Authorization", "Bearer "+c.apiKey)
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", "meeng-go/"+Version)
	if encoded != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", idempotencyKey)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return 0, err
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return 0, err
	}
	if resp.StatusCode >= 300 {
		refusal := errorOf(resp, raw)
		return refusal.RetryAfter, refusal
	}
	if out == nil {
		return 0, nil
	}
	if err := json.Unmarshal(raw, out); err != nil {
		return 0, &decodeError{err}
	}
	return 0, nil
}

// decodeError is an answer that arrived and could not be read: repeating the
// call would not change it.
type decodeError struct{ err error }

func (e *decodeError) Error() string { return e.err.Error() }
func (e *decodeError) Unwrap() error { return e.err }

func isDecodeError(err error) bool {
	var d *decodeError
	return errors.As(err, &d)
}

// repeatable says a call cannot do its work twice: a read, a PUT, a DELETE, or
// a call with an Idempotency-Key.
func repeatable(method, idempotencyKey string) bool {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete:
		return true
	}
	return idempotencyKey != ""
}

// transient says the status is a failure that passes.
func transient(status int) bool {
	switch status {
	case http.StatusInternalServerError, http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusGatewayTimeout:
		return true
	}
	return false
}

// backoff is the wait before repetition number attempt+1: the base delay
// doubled each time, spread over its upper half so that clients that failed
// together do not come back together.
func (c *Client) backoff(attempt int) time.Duration {
	delay := c.retryDelay << min(attempt, 10)
	if delay <= 0 {
		return 0
	}
	if delay > MaxRetryDelay {
		delay = MaxRetryDelay
	}
	return delay/2 + time.Duration(rand.Int64N(int64(delay/2)+1))
}

// errorOf reads a refused answer: {"error":{"code","message"}}, {"error":"text"}
// or the error itself, {"code","message"}.
func errorOf(resp *http.Response, raw []byte) *Error {
	e := &Error{StatusCode: resp.StatusCode, Code: "INTERNAL_SERVER_ERROR", Message: http.StatusText(resp.StatusCode)}
	var body struct {
		Error   json.RawMessage `json:"error"`
		Code    string          `json:"code"`
		Message string          `json:"message"`
	}
	if json.Unmarshal(raw, &body) == nil {
		code, message := body.Code, body.Message
		if len(body.Error) > 0 {
			// A refused validation answers {"success": false, "error": {"issues", "name"}}, with no code of its own.
			var nested struct {
				Code    string `json:"code"`
				Name    string `json:"name"`
				Message string `json:"message"`
				Issues  []struct {
					Path    []any  `json:"path"`
					Message string `json:"message"`
				} `json:"issues"`
			}
			var text string
			if json.Unmarshal(body.Error, &nested) == nil {
				code, message = nested.Code, nested.Message
				if code == "" {
					code = nested.Name
				}
				if message == "" && len(nested.Issues) > 0 {
					parts := make([]string, len(nested.Issues[0].Path))
					for i, part := range nested.Issues[0].Path {
						parts[i] = fmt.Sprint(part)
					}
					message = nested.Issues[0].Message
					if len(parts) > 0 {
						message = strings.Join(parts, ".") + ": " + message
					}
				}
			} else if json.Unmarshal(body.Error, &text) == nil {
				code, message = "", text
			}
		}
		if code != "" {
			e.Code = code
		}
		if message != "" {
			e.Message = message
		}
	}
	if seconds, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil {
		e.RetryAfter = time.Duration(seconds) * time.Second
	}
	return e
}
